"use client";

import type { ChartRoot } from "./chart-utils";
import { useChartDirection } from "./chart-pointer";
import { useMergedRef } from "../lib/form";
import {
  startTransition,
  useCallback,
  useEffect,
  useMemo,
  useRef,
  useState,
  type KeyboardEvent,
  type PointerEvent as ReactPointerEvent,
  type ReactNode,
  useLayoutEffect,
} from "react";
import { AnimatePresence, motion } from "motion/react";
import { cn } from "../lib/cn";
import { duration, ease } from "../motion/tokens";
import { useSheenReducedMotion } from "../hooks/use-preferences";
import { ChartEmpty } from "./chart-parts";
import { useDockedReadout, useInputSource } from "./chart-fit";
import { useCoarsePointer } from "../hooks/use-media-query";
import { clamp, slotColor, useElementWidth, resolveInstructions } from "./chart-utils";
import { ChartDockHint, useEntrance } from "./heatmap";
import { localeWeekStart } from "./calendar-heatmap";
import { ChartFigure } from "./chart-figure";
import { defaultGanttChartLabels, type GanttScale, type GanttChartProps } from "./gantt/types";
import {
  ganttDay,
  ymd,
  monthStart,
  PX_PER_DAY,
  ORDER,
  slotOf,
  buildModel,
  type TaskRow,
  type Row,
} from "./gantt/model";
import {
  DOCK_BAND,
  HEADER,
  BAR_H,
  DIAMOND,
  isolate,
  cssEase,
  DockedReadout,
  StableTip,
  syncTimeline,
  scrollStart,
  setScrollStart,
} from "./gantt/layout";
import { describeGanttTask, ganttPercent } from "./gantt/describe";
import { startGanttGlide } from "./gantt/glide";
import { buildArrows } from "./gantt/arrows";
import { buildTicks, ganttFormats } from "./gantt/ticks";
import { createActiveStore, type Links } from "./gantt/store";
import { LabelRow, BarRow, GroupBracket, IdleArrows, HotArrows } from "./gantt/rows";
import { GanttToolbar } from "./gantt/toolbar";
import { GanttOverlay } from "./gantt/overlay";
import { LabelHighlight, TimelineHighlight, GanttReadout, GanttAnnouncer, GridLayer, type Ticks } from "./gantt/layers";

export {
  type GanttTask,
  type GanttScale,
  type GanttChartLabels,
  defaultGanttChartLabels,
  type GanttChartProps,
} from "./gantt/types";
export { ganttDay, ganttLegend } from "./gantt/model";
export { type GanttTableProps, GanttTable } from "./gantt/table";

/**
 * Gantt chart: tasks as bars on a timeline, with progress, finish-to-start dependency arrows,
 * milestones, collapsible phases and a today line.
 *
 * - Zoom between days, weeks and months; by default it opens at the most detailed zoom that fits
 *   the whole plan. A zoom change glides around the date in the middle of the view (one
 *   compositor transform for the bars and grid, so it stays smooth on any plan size). Short
 *   plans stretch to fill the width.
 * - The task names stay put while the timeline scrolls sideways inside its own container (on a
 *   phone, a month of days is wider than the screen: it never widens the page); an edge fades
 *   while there's more plan beyond it.
 * - Hover or tap a bar for a glass tooltip (it pins on touch; docked on narrow touch screens);
 *   the task's arrows light up. Focus the timeline: ↑ ↓ move between tasks, ← → scroll, T jumps
 *   to today, + / − zoom; Enter calls onTaskClick.
 * - Bars grow from their start date in a cascade, then the arrows draw in and milestones pop;
 *   rows glide when a phase collapses. Instant with reduced motion.
 * - Right-to-left pages get a mirrored timeline (time runs leftwards).
 *
 * Keyboard: Tab focuses the timeline; Up and Down move between tasks, Left and Right scroll the timeline (mirrored in right-to-left), Home and End jump to the first and last task, T jumps to today, + and - zoom between day, week and month, Escape clears. Enter calls `onTaskClick`. The toolbar buttons (zoom, today, collapse) are normal tab stops.
 * Accessibility: `role="figure"` named by the chart title, with the keyboard hint as its description (`aria-describedby`, and `aria-details` to the `ChartCard` table view); focusable only when interactive; keyboard moves announce the task with its dates, progress and dependencies, and the timeline scrolls inside its own container instead of widening the page. `GanttTable` is the table view.
 * Glass and motion: the tooltip is the shared glass surface; the bars and grid are plain SVG. Reduced motion draws and zooms instantly.
 *
 * @example
 * ```tsx
 * import { GanttChart } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <GanttChart
 *       tasks={[
 *         { id: "design", label: "Design", start: "2026-03-02", end: "2026-03-11", progress: 1 },
 *         { id: "build", label: "Build", start: "2026-03-12", end: "2026-03-27", progress: 0.6, dependencies: ["design"] },
 *         { id: "launch", label: "Launch", start: "2026-04-01", milestone: true, dependencies: ["build"] },
 *       ]}
 *       aria-label="Project plan, March to April"
 *     />
 *   );
 * }
 * ```
 *
 * @see /charts/gantt
 */
export function GanttChart({
  tasks,
  scale: scaleProp,
  defaultScale = "auto",
  onScaleChange,
  toolbar = true,
  today: todayProp,
  locale,
  labelWidth,
  collapsible = true,
  defaultCollapsed = [],
  onTaskClick,
  emptyState,
  labels: labelOverrides,
  "aria-label": ariaLabel,
  className,
  ref: outerRef,
  ...rest
}: ChartRoot<GanttChartProps>) {
  const labels = { ...defaultGanttChartLabels, ...labelOverrides };
  const reduced = useSheenReducedMotion();
  const coarse = useCoarsePointer();
  const rootRef = useRef<HTMLDivElement>(null);
  const rootMerged = useMergedRef(rootRef, outerRef);
  const scrollRef = useRef<HTMLDivElement>(null);
  const stretchRef = useRef<SVGSVGElement>(null);
  const overlayRef = useRef<SVGSVGElement>(null);
  const fadeRef = useRef<SVGGElement>(null);
  const [measureRef, width] = useElementWidth<HTMLDivElement>();
  const play = useEntrance(rootRef, reduced);
  const docked = useDockedReadout(width);
  const { fromKeyboard, fromPointer, announce } = useInputSource();

  /* ---------- Model ---------- */

  const { taskRows, groups } = useMemo(() => buildModel(tasks), [tasks]);
  const hasTasks = taskRows.length > 0;
  const rtl = useChartDirection(rootRef);
  const todayDay = todayProp === null ? null : (ganttDay(todayProp ?? new Date()) ?? null);
  const [collapsed, setCollapsed] = useState<ReadonlySet<string>>(() => new Set(defaultCollapsed));

  const [rangeStart, rangeEnd] = useMemo(() => {
    if (!taskRows.length) return [0, 1];
    let lo = Infinity;
    let hi = -Infinity;
    for (const t of taskRows) {
      lo = Math.min(lo, t.start);
      hi = Math.max(hi, t.end);
    }
    // Whole months around the plan (a day of air on each side).
    const a = ymd(lo - 1);
    const b = ymd(hi + 1);
    return [monthStart(a.y, a.m), monthStart(b.y, b.m + 1)];
  }, [taskRows]);
  const totalDays = Math.max(1, rangeEnd - rangeStart);

  const byId = useMemo(() => new Map(taskRows.map((t) => [t.task.id, t])), [taskRows]);

  /** Visible rows (groups and the tasks of expanded groups), in order. */
  const rows = useMemo<Row[]>(() => {
    const out: Row[] = [];
    for (const t of taskRows) if (!t.group) out.push(t);
    groups.forEach((g, gi) => {
      const members = taskRows.filter((t) => t.group === g);
      if (!members.length) return;
      out.push({
        kind: "group",
        key: `\u0000group:${g}`,
        name: g,
        start: Math.min(...members.map((m) => m.start)),
        end: Math.max(...members.map((m) => m.end)),
        count: members.length,
        color: slotOf(gi),
      });
      if (!collapsed.has(g)) out.push(...members);
    });
    return out;
  }, [taskRows, groups, collapsed]);

  /* ---------- Geometry ---------- */

  const rowH = coarse ? 44 : 36;
  const groupH = coarse ? 44 : 32;
  const longest = taskRows.reduce(
    (n, t) => Math.max(n, t.task.label.length),
    Math.max(...groups.map((g) => g.length + 4), 0),
  );
  const labelW =
    labelWidth ??
    Math.round(clamp(longest * 7 + 36, 104, Math.max(104, Math.min(260, width * (width < 520 ? 0.38 : 0.3)))));
  const viewW = Math.max(0, width - labelW);
  const fitPx = viewW / totalDays;

  // Uncontrolled and untouched: the most detailed zoom at which the whole plan fits.
  const [innerScale, setInnerScale] = useState<GanttScale | null>(defaultScale === "auto" ? null : defaultScale);
  const autoScale: GanttScale = fitPx >= PX_PER_DAY.day ? "day" : fitPx >= PX_PER_DAY.week ? "week" : "month";
  const scale = scaleProp ?? innerScale ?? autoScale;
  // A zoom re-renders every bar and tick: a transition, so the render is sliced and never blocks input.
  const setScale = (s: GanttScale) =>
    startTransition(() => {
      if (scaleProp === undefined) setInnerScale(s);
      onScaleChange?.(s);
    });

  const px = Math.max(PX_PER_DAY[scale], fitPx);
  const contentW = Math.ceil(totalDays * px);
  /** Inline-start offset of a day. */
  const xOf = (day: number) => (day - rangeStart) * px;
  /** Inline-start offset → x in the SVG (mirrored on right-to-left pages). */
  const X = (offset: number) => (rtl ? contentW - offset : offset);
  /** Box of the span [a, b) in SVG x. */
  const span = (a: number, b: number) => {
    const s = xOf(a);
    const e = xOf(b);
    return rtl ? { x: contentW - e, w: e - s } : { x: s, w: e - s };
  };

  const rowY = useMemo(() => {
    const ys: number[] = [];
    let y = HEADER;
    for (const r of rows) {
      ys.push(y);
      y += r.kind === "group" ? groupH : rowH;
    }
    ys.push(y);
    return ys;
  }, [rows, rowH, groupH]);
  const height = rowY[rowY.length - 1] ?? HEADER;
  const rowIndex = useMemo(() => new Map(rows.map((r, i) => [r.key, i])), [rows]);
  const taskOrder = useMemo(() => rows.flatMap((r, i) => (r.kind === "task" ? [i] : [])), [rows]);

  /* ---------- Active task ---------- */

  const store = useMemo(() => createActiveStore(), []);
  const posRef = useRef(0);
  const activate = useCallback((key: string | null) => store.set({ key, scroll: posRef.current }), [store]);

  /** Each task's partners by an arrow (either way): they light up with it. */
  const links = useMemo<Links>(() => {
    const map = new Map<string, Set<string>>();
    const link = (a: string, b: string) => {
      const set = map.get(a);
      if (set) set.add(b);
      else map.set(a, new Set([b]));
    };
    const ids = new Set(taskRows.map((t) => t.task.id));
    for (const t of taskRows)
      for (const dep of t.task.dependencies ?? [])
        if (ids.has(dep) && dep !== t.task.id) {
          link(t.task.id, dep);
          link(dep, t.task.id);
        }
    return map;
  }, [taskRows]);

  /* ---------- Scrolling: written to the DOM, never a render per frame ---------- */

  const sync = useCallback(() => {
    const el = scrollRef.current;
    const overlay = overlayRef.current;
    if (el && overlay) syncTimeline(el, overlay, posRef.current);
  }, []);
  const raf = useRef(0);
  const onScroll = () => {
    const el = scrollRef.current;
    if (!el) return;
    posRef.current = scrollStart(el, rtl);
    if (raf.current) return;
    raf.current = requestAnimationFrame(() => {
      raf.current = 0;
      sync();
      const { key } = store.get();
      if (key !== null) store.set({ key, scroll: posRef.current }); // keep the tooltip on its bar
    });
  };
  useEffect(() => () => cancelAnimationFrame(raf.current), []);

  // First layout: the plan's start, unless that would leave today out of view: then today, a third
  // of the way in. Again if the page's direction flips.
  const placedFor = useRef<boolean | null>(null);
  useLayoutEffect(() => {
    const el = scrollRef.current;
    if (placedFor.current === rtl || !el || width === 0 || !taskRows.length) return;
    placedFor.current = rtl;
    const first = Math.min(...taskRows.map((t) => t.start));
    const startAt = (first - rangeStart) * px - 24;
    const view = el.clientWidth;
    const todayAt =
      todayDay !== null && todayDay >= rangeStart && todayDay < rangeEnd ? (todayDay - rangeStart) * px : null;
    setScrollStart(
      el,
      rtl,
      todayAt === null || (todayAt > startAt + 40 && todayAt < startAt + view - 40) ? startAt : todayAt - view / 3,
    );
    posRef.current = scrollStart(el, rtl);
    sync();
  }, [width, taskRows, rtl, px, rangeStart, rangeEnd, todayDay, sync]);

  // A zoom (or resize) keeps the day in the middle of the view where it is. A zoom also GLIDES:
  // the bars and grid render once at the new zoom, then one transform (on the compositor) takes
  // them from where they were to where they are; diamonds slide, labels fade back in.
  const [gliding, setGliding] = useState(false);
  const flips = useRef<Animation[]>([]);
  const before = useRef<{ px: number; width: number; scale: GanttScale } | null>(null);
  useLayoutEffect(() => {
    const prev = before.current;
    before.current = { px, width, scale };
    const el = scrollRef.current;
    if (!prev || !el || prev.width === 0 || width === 0 || prev.px === px || placedFor.current === null) return;
    const view = el.clientWidth;
    const from = posRef.current;
    const anchor = (from + view / 2) / prev.px;
    setScrollStart(el, rtl, anchor * px - view / 2);
    const to = scrollStart(el, rtl);
    posRef.current = to;
    sync();
    if (prev.scale === scale || prev.width !== width || reduced) return;

    for (const a of flips.current) a.cancel();
    const list = startGanttGlide({
      fromPx: prev.px,
      px,
      shift: (rtl ? -1 : 1) * (to - from),
      rtl,
      contentW,
      stretch: stretchRef.current,
      overlay: overlayRef.current,
      fade: fadeRef.current,
    });
    flips.current = list;
    const lead = list[0];
    if (!lead) return;
    // The glide is started here with the Web Animations API, from layout measured in this effect; the state only marks it running.
    setGliding(true);
    lead.finished.then(
      () => {
        setGliding(false);
        const { key } = store.get();
        store.set({ key, scroll: posRef.current });
      },
      () => undefined, // cancelled by the next zoom, which takes over
    );
  }, [px, width, scale, rtl, reduced, contentW, sync, store]);
  useEffect(() => () => flips.current.forEach((a) => a.cancel()), []);

  // A lit-up arrow fades in when it appears (a stable ref callback: no component, no state).
  const fadeIn = useCallback(
    (el: SVGGElement | null) => {
      if (el && !reduced && typeof el.animate === "function")
        el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: duration.fast * 1000, easing: cssEase(ease.out) });
    },
    [reduced],
  );

  // Rows drawn in the first commit with a width are the first view (no fade-in); later ones fade in.
  // (Children's layout effects run before this one, so they still see `true` in that commit.)
  const firstView = useRef(true);
  // Long plans skip the collapse glide: a hundred rows animating at once would not stay smooth.
  const glide = rows.length <= 60;
  useLayoutEffect(() => {
    if (width > 0 && hasTasks) firstView.current = false;
  });

  // The arrows draw in once; arrows that light up later (hover) just fade in.
  const [settled, setSettled] = useState(false);
  useEffect(() => {
    if (!play || settled) return;
    const t = window.setTimeout(() => setSettled(true), 1900);
    return () => window.clearTimeout(t);
  }, [play, settled]);

  /* ---------- Ticks ---------- */

  const fmt = useMemo(() => ganttFormats(locale), [locale]);
  const weekStart = useMemo(() => localeWeekStart(locale), [locale]);

  const ticks = useMemo<Ticks>(
    () => buildTicks(rangeStart, rangeEnd, scale, fmt, weekStart),
    [rangeStart, rangeEnd, scale, fmt, weekStart],
  );

  // New or moved labels get their sticky position / visibility before they paint. (Only when the
  // geometry changes: a hover never pays for it.)
  useLayoutEffect(() => {
    sync();
  }, [sync, ticks, rows, rowY, px, contentW, viewW, rtl]);

  // Arrows: finish-to-start. They leave from under the end of the predecessor (so they never cross
  // its progress label) and enter the successor's start from the side.
  const arrows = useMemo(
    () => buildArrows({ rows, byId, rowIndex, rowY, rowH, rangeStart, px, rtl, contentW }),
    [rows, rowIndex, rowY, byId, rangeStart, px, rowH, rtl, contentW],
  );

  /* ---------- Handlers ---------- */

  const toggleGroup = useCallback(
    (name: string) =>
      setCollapsed((prev) => {
        const next = new Set(prev);
        if (next.has(name)) next.delete(name);
        else next.add(name);
        return next;
      }),
    [],
  );
  const onLabelEnter = useCallback(
    (key: string) => {
      fromPointer();
      activate(key);
    },
    [fromPointer, activate],
  );
  const onLabelLeave = useCallback(() => activate(null), [activate]);

  const revealTask = (row: TaskRow) => {
    const el = scrollRef.current;
    if (!el) return;
    const a = xOf(row.start) - (row.milestone ? DIAMOND : 0);
    const b = xOf(row.end) + (row.milestone ? DIAMOND : 0);
    const s = scrollStart(el, rtl);
    const view = el.clientWidth;
    if (a >= s + 16 && b <= s + view - 16) return;
    const target = b - a > view - 32 ? a - 24 : a - Math.max(24, (view - (b - a)) / 3);
    setScrollStart(el, rtl, target, !reduced);
  };

  function moveTo(i: number | undefined) {
    if (i === undefined) return;
    const row = rows[i];
    if (row?.kind !== "task") return;
    fromKeyboard();
    activate(row.key);
    revealTask(row);
  }

  function onKeyDown(event: KeyboardEvent<HTMLDivElement>) {
    const activeKey = store.get().key;
    const activeRow = activeKey === null ? undefined : rows[rowIndex.get(activeKey) ?? -1];
    const activeTask = activeRow?.kind === "task" ? activeRow : null;
    const cur = activeTask ? taskOrder.indexOf(rowIndex.get(activeTask.key) ?? -1) : -1;
    const el = scrollRef.current;
    const unit = scale === "day" ? px : scale === "week" ? px * 7 : px * 30;
    switch (event.key) {
      case "ArrowDown":
        moveTo(taskOrder[cur < 0 ? 0 : Math.min(taskOrder.length - 1, cur + 1)]);
        break;
      case "ArrowUp":
        moveTo(taskOrder[cur < 0 ? 0 : Math.max(0, cur - 1)]);
        break;
      case "Home":
        moveTo(taskOrder[0]);
        break;
      case "End":
        moveTo(taskOrder[taskOrder.length - 1]);
        break;
      case "ArrowRight":
      case "ArrowLeft": {
        if (!el) return;
        const forward = (event.key === "ArrowRight") !== rtl;
        setScrollStart(el, rtl, scrollStart(el, rtl) + (forward ? unit : -unit), !reduced);
        break;
      }
      case "t":
      case "T":
        if (todayDay === null || !el) return;
        setScrollStart(el, rtl, xOf(todayDay) - el.clientWidth / 3, !reduced);
        break;
      case "+":
      case "=":
      case "-":
      case "_": {
        const i = ORDER.indexOf(scale);
        const next = ORDER[clamp(i + (event.key === "+" || event.key === "=" ? 1 : -1), 0, ORDER.length - 1)];
        if (next && next !== scale) setScale(next);
        break;
      }
      case "Enter":
      case " ":
        if (!activeTask || !onTaskClick) return;
        onTaskClick(activeTask.task);
        break;
      case "Escape":
        if (activeKey === null) return;
        activate(null);
        break;
      default:
        return;
    }
    event.preventDefault();
  }

  /** The row under a pointer event on the timeline. */
  const rowAt = (event: ReactPointerEvent<HTMLDivElement>) => {
    const y = event.clientY - event.currentTarget.getBoundingClientRect().top;
    const i = rowY.findIndex((top, k) => y >= top && y < (rowY[k + 1] ?? -1));
    return rows[i];
  };

  /* ---------- Formatting ---------- */

  const pct = useMemo(() => ganttPercent(locale), [locale]);
  const describe = (row: TaskRow) => describeGanttTask(row, { fmt, labels, pct, byId });

  if (!hasTasks) {
    return (
      <ChartEmpty height={240} aria-label={ariaLabel} className={className}>
        {emptyState}
      </ChartEmpty>
    );
  }

  /* ---------- Tooltip ---------- */

  const dock = docked ? DOCK_BAND : 0;
  /** The reading of the task `key` (with the timeline scrolled to `scroll`): the tooltip or the docked readout. */
  const read = (key: string, scroll: number): ReactNode => {
    const row = rows[rowIndex.get(key) ?? -1];
    if (row?.kind !== "task" || width === 0 || gliding) return null;
    const i = rowIndex.get(row.key) ?? 0;
    const y = rowY[i] ?? 0;
    const box = row.milestone ? { x: X(xOf(row.start) + px / 2) - DIAMOND / 2, w: DIAMOND } : span(row.start, row.end);
    // From timeline coordinates to the chart box: past the label column, minus the scroll.
    const scrolledX = rtl ? box.x - (contentW - viewW - scroll) : box.x - scroll;
    const left = clamp(scrolledX, -box.w, viewW) + (rtl ? 0 : labelW);
    const parts = describe(row);
    return docked ? (
      <DockedReadout
        title={row.task.label}
        value={parts[0] ?? ""}
        color={slotColor(row.color)}
        details={parts.slice(1)}
      />
    ) : (
      <StableTip
        title={isolate(row.task.label)}
        rows={parts.map((p, k) => ({
          label: k === 0 ? "" : isolate(p),
          value: k === 0 ? isolate(p) : "",
          color: k === 0 ? slotColor(row.color) : "transparent",
          kind: "rect" as const,
        }))}
        anchor={{ x: left, y: y + (rowH - BAR_H) / 2, w: Math.min(box.w, viewW), h: BAR_H }}
        bounds={{ w: width, h: height }}
        order={["below", "above", rtl ? "left" : "right", rtl ? "right" : "left"]}
      />
    );
  };
  /** What a keyboard move to `key` announces (nothing for pointer reads). */
  const announcement = (key: string) => {
    const row = rows[rowIndex.get(key) ?? -1];
    return row?.kind === "task" ? announce(`${row.task.label}: ${describe(row).join(", ")}`) : "";
  };

  /* ---------- Render ---------- */

  const todayIn = todayDay !== null && todayDay >= rangeStart && todayDay < rangeEnd;
  const todayX = todayDay === null ? 0 : X(xOf(todayDay) + px / 2);
  const countText = (n: number) => (labelW >= 160 ? labels.tasks(n) : null);

  return (
    <div {...rest} ref={rootMerged} className={cn("relative flex w-full min-w-0 flex-col gap-3", className)}>
      {toolbar && (
        <GanttToolbar
          labels={labels}
          scale={scale}
          onScale={setScale}
          showToday={todayDay !== null}
          todayEnabled={todayIn}
          onToday={() => {
            const el = scrollRef.current;
            if (el && todayDay !== null) setScrollStart(el, rtl, xOf(todayDay) - el.clientWidth / 3, !reduced);
          }}
        />
      )}

      <div ref={measureRef} className="relative w-full" style={{ paddingTop: dock }}>
        {width > 0 && (
          <div className="flex w-full" style={{ height }}>
            {/* Task names stay put while the timeline scrolls; phase rows are real disclosure buttons. */}
            <div className="relative shrink-0 overflow-hidden border-e border-sheen-border" style={{ width: labelW }}>
              <p
                aria-hidden
                className="absolute inset-x-0 top-0 flex items-end px-2 pb-1.5 text-xs font-medium text-sheen-fg-muted"
                style={{ height: HEADER }}
              >
                {labels.task}
              </p>
              {/* Sliding highlight behind the active row. */}
              <LabelHighlight store={store} rowIndex={rowIndex} rowY={rowY} rowH={rowH} reduced={reduced} />
              <AnimatePresence initial={false}>
                {rows.map((row, i) => (
                  <LabelRow
                    key={row.key}
                    row={row}
                    y={rowY[i] ?? 0}
                    height={row.kind === "group" ? groupH : rowH}
                    store={store}
                    links={links}
                    collapsed={row.kind === "group" && collapsed.has(row.name)}
                    collapsible={collapsible}
                    countText={row.kind === "group" ? countText(row.count) : null}
                    reduced={reduced}
                    glide={glide}
                    firstView={firstView}
                    onEnter={onLabelEnter}
                    onLeave={onLabelLeave}
                    onToggle={toggleGroup}
                  />
                ))}
              </AnimatePresence>
            </div>

            {/* The timeline: one focusable, sideways-scrolling region. Its focus ring is drawn by the
                wrapper, outside the edge-fade mask. */}
            <div className="relative min-w-0 flex-1 rounded-sheen-sm has-[:focus-visible]:outline-solid has-[:focus-visible]:outline-2 has-[:focus-visible]:outline-offset-2 has-[:focus-visible]:outline-sheen-focus">
              <ChartFigure
                as="div"
                ref={scrollRef}
                roleDescription={labels.roleDescription}
                label={ariaLabel}
                description={resolveInstructions(labels.instructions)}
                tabIndex={0}
                onKeyDown={onKeyDown}
                onScroll={onScroll}
                onBlur={() => activate(null)}
                onPointerLeave={(e) => e.pointerType === "mouse" && activate(null)}
                className={cn(
                  "relative overflow-x-auto overflow-y-hidden overscroll-x-contain outline-none [scrollbar-width:thin]",
                  "data-fade:[mask-image:linear-gradient(to_right,transparent,#000_var(--gantt-fade-l),#000_calc(100%_-_var(--gantt-fade-r)),transparent)]",
                )}
              >
                {/* eslint-disable-next-line jsx-a11y/click-events-have-key-events, jsx-a11y/no-static-element-interactions -- pointer-only hit area over the timeline; the keyboard equivalent is the focusable timeline group around it */}
                <div
                  className="relative"
                  style={{ width: contentW, height }}
                  onPointerMove={(e) => {
                    if (e.pointerType !== "mouse") return;
                    const row = rowAt(e);
                    fromPointer();
                    activate(row?.kind === "task" ? row.key : null);
                  }}
                  onPointerDown={(e) => {
                    if (e.pointerType === "mouse") return;
                    const row = rowAt(e);
                    fromPointer();
                    activate(row?.kind === "task" ? row.key : null);
                  }}
                  onClick={(e) => {
                    if (!onTaskClick) return;
                    const y = e.clientY - e.currentTarget.getBoundingClientRect().top;
                    const row = rows[rowY.findIndex((top, k) => y >= top && y < (rowY[k + 1] ?? -1))];
                    if (row?.kind === "task") onTaskClick(row.task);
                  }}
                >
                  {/* Bars, grid and arrows: one layer a zoom stretches on the compositor. */}
                  <svg
                    ref={stretchRef}
                    aria-hidden
                    width={contentW}
                    height={height}
                    className="block"
                    // Coordinates are already mirrored for right-to-left pages: anchors must stay physical.
                    style={{ direction: "ltr", transformOrigin: rtl ? "100% 0" : "0 0" }}
                  >
                    <GridLayer
                      ticks={ticks}
                      weekends={scale === "day"}
                      rangeStart={rangeStart}
                      px={px}
                      contentW={contentW}
                      height={height}
                      rtl={rtl}
                    />

                    {/* Active row highlight (glides between rows). */}
                    <TimelineHighlight
                      store={store}
                      rowIndex={rowIndex}
                      rowY={rowY}
                      rowH={rowH}
                      width={contentW}
                      reduced={reduced}
                    />

                    {/* Today: under the bars and their labels, so it never strikes through a value. */}
                    {todayIn && (
                      <motion.line
                        x1={todayX}
                        x2={todayX}
                        y1={HEADER}
                        y2={height}
                        strokeWidth={1.5}
                        className="pointer-events-none stroke-sheen-accent forced-colors:stroke-[Highlight]"
                        style={{
                          filter: "drop-shadow(0 0 4px light-dark(transparent, var(--sheen-accent-glow)))",
                          originY: 0,
                        }}
                        initial={reduced ? false : { scaleY: 0 }}
                        animate={play ? { scaleY: 1 } : undefined}
                        transition={
                          reduced ? { duration: 0 } : { duration: duration.slower, ease: ease.out, delay: 0.2 }
                        }
                      />
                    )}

                    {/* Idle arrows run under the bars, so they never cover a task. */}
                    <IdleArrows store={store} arrows={arrows} play={play} reduced={reduced} settled={settled} />

                    {/* Phase brackets and task bars. */}
                    <AnimatePresence initial={false}>
                      {rows.map((row, i) => {
                        const y = rowY[i] ?? 0;
                        if (row.kind === "group") {
                          const { x, w } = span(row.start, row.end);
                          return (
                            <GroupBracket
                              key={row.key}
                              y={y}
                              x={x}
                              w={w}
                              groupH={groupH}
                              color={row.color}
                              order={i}
                              play={play}
                              reduced={reduced}
                              glide={glide}
                              firstView={firstView}
                            />
                          );
                        }
                        if (row.milestone) return null;
                        const { x, w } = span(row.start, row.end);
                        return (
                          <BarRow
                            key={row.key}
                            index={row.index}
                            y={y}
                            x={x}
                            w={Math.max(2, w - 2)}
                            rowH={rowH}
                            color={row.color}
                            progress={row.progress}
                            rowKey={row.key}
                            store={store}
                            rtl={rtl}
                            play={play}
                            reduced={reduced}
                            order={i}
                            glide={glide}
                            firstView={firstView}
                          />
                        );
                      })}
                    </AnimatePresence>

                    {/* The active task's arrows, lit up above the bars. */}
                    <HotArrows store={store} arrows={arrows} fadeIn={fadeIn} />
                  </svg>

                  <GanttOverlay
                    svgRef={overlayRef}
                    fadeRef={fadeRef}
                    store={store}
                    rows={rows}
                    rowY={rowY}
                    rowH={rowH}
                    ticks={ticks}
                    scale={scale}
                    rangeStart={rangeStart}
                    px={px}
                    contentW={contentW}
                    viewW={viewW}
                    height={height}
                    rtl={rtl}
                    todayDay={todayDay}
                    todayIn={todayIn}
                    todayX={todayX}
                    X={X}
                    xOf={xOf}
                    fmt={fmt}
                    pct={pct}
                    play={play}
                    reduced={reduced}
                    glide={glide}
                    firstView={firstView}
                  />
                </div>
              </ChartFigure>
            </div>
          </div>
        )}
        {width === 0 && <div aria-hidden style={{ height: HEADER + rows.length * rowH }} />}
        <GanttReadout
          store={store}
          read={read}
          fallback={docked ? <ChartDockHint>{labels.hint}</ChartDockHint> : null}
        />
      </div>

      <GanttAnnouncer store={store} text={announcement} />
    </div>
  );
}

import { BAR_H, DIAMOND } from "./layout";
import { roundedPath, type Row, type TaskRow } from "./model";

/** One finish-to-start dependency arrow: its path and arrow head. @internal */
export type GanttArrow = { key: string; from: string; to: string; d: string; head: string };

/** The geometry the dependency arrows are laid out on. @internal */
export type GanttArrowInput = {
  rows: Row[];
  byId: Map<string, TaskRow>;
  rowIndex: Map<string, number>;
  rowY: number[];
  rowH: number;
  rangeStart: number;
  px: number;
  rtl: boolean;
  contentW: number;
};

/**
 * Arrows: finish-to-start. They leave from under the end of the predecessor (so they never cross its
 * progress label) and enter the successor's start from the side.
 * @internal
 */
export function buildArrows(o: GanttArrowInput): GanttArrow[] {
  const { rows, byId, rowIndex, rowY, rowH, rangeStart, px, rtl, contentW } = o;
  const list: { key: string; from: string; to: string; d: string; head: string }[] = [];
  const at = (day: number) => (day - rangeStart) * px;
  const mirror = (o: number) => (rtl ? contentW - o : o);
  rows.forEach((row) => {
    if (row.kind !== "task") return;
    for (const depId of row.task.dependencies ?? []) {
      const from = byId.get(depId);
      if (!from || from.task.id === row.task.id) continue;
      const fi = rowIndex.get(from.key);
      const ti = rowIndex.get(row.key);
      if (fi === undefined || ti === undefined) continue; // one end is collapsed away
      const dir = ti > fi ? 1 : -1;
      const y1mid = (rowY[fi] ?? 0) + rowH / 2;
      const y2 = (rowY[ti] ?? 0) + rowH / 2;
      let x1: number;
      let y1: number;
      if (from.milestone) {
        x1 = at(from.start) + px / 2;
        y1 = y1mid + dir * (DIAMOND * 0.72);
      } else {
        const w = at(from.end) - at(from.start) - 2;
        x1 = at(from.start) + Math.max(2, w - Math.min(10, w / 3));
        y1 = y1mid + dir * (BAR_H / 2);
      }
      const x2 = row.milestone ? at(row.start) + px / 2 - DIAMOND * 0.72 - 1 : at(row.start) - 1;
      const g = 9;
      // Room to come straight down and turn in: an L. Otherwise step back along the gap between rows.
      const between = y1mid + dir * (rowH / 2);
      const pts: [number, number][] =
        x2 - x1 >= g
          ? [
              [x1, y1],
              [x1, y2],
              [x2, y2],
            ]
          : [
              [x1, y1],
              [x1, between],
              [x2 - g, between],
              [x2 - g, y2],
              [x2, y2],
            ];
      const tip = mirror(x2);
      const head = rtl ? -1 : 1;
      list.push({
        key: `${depId}\u0000${row.key}`,
        from: depId,
        to: row.task.id,
        d: roundedPath(pts.map(([x, y]) => [mirror(x), y] as [number, number])),
        head: `M${tip - head * 5},${y2 - 3.5}L${tip},${y2}L${tip - head * 5},${y2 + 3.5}`,
      });
    }
  });
  return list;
}

import { dateOf, type TaskRow } from "./model";
import type { GanttChartLabels } from "./types";
import type { ganttFormats } from "./ticks";

/** A whole-number percent formatter in the chart's locale (English when it is unknown). @internal */
export function ganttPercent(locale: string | undefined) {
  try {
    return new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 });
  } catch {
    return new Intl.NumberFormat("en", { style: "percent", maximumFractionDigits: 0 });
  }
}

/** The date range of a task: one date for a milestone, a formatted range otherwise. @internal */
export function ganttRangeText(row: TaskRow, fmt: ReturnType<typeof ganttFormats>) {
  if (row.milestone) return fmt.full.format(dateOf(row.start));
  const a = dateOf(row.start);
  const b = dateOf(row.end - 1);
  const f = fmt.full as Intl.DateTimeFormat & { formatRange?: (x: Date, y: Date) => string };
  return typeof f.formatRange === "function" ? f.formatRange(a, b) : `${f.format(a)} – ${f.format(b)}`;
}

/** The spoken and tooltip parts of a task: dates, duration, progress, predecessors and assignee. @internal */
export function describeGanttTask(
  row: TaskRow,
  o: {
    fmt: ReturnType<typeof ganttFormats>;
    labels: GanttChartLabels;
    pct: Intl.NumberFormat;
    byId: Map<string, TaskRow>;
  },
) {
  const { fmt, labels, pct, byId } = o;
  const parts = [ganttRangeText(row, fmt)];
  if (row.milestone) parts.push(labels.milestone);
  else parts.push(labels.duration(row.end - row.start));
  if (row.progress !== null && !row.milestone) parts.push(labels.progress(pct.format(row.progress)));
  const deps = (row.task.dependencies ?? []).map((id) => byId.get(id)?.task.label).filter((n): n is string => !!n);
  if (deps.length) parts.push(labels.after(deps.join(", ")));
  if (row.task.assignee) parts.push(row.task.assignee);
  return parts;
}

import { duration, ease } from "../../motion/tokens";
import { cssEase } from "./layout";

/** What a zoom glide animates. @internal */
export type GanttGlideInput = {
  /** The px-per-day before and after the zoom. */
  fromPx: number;
  px: number;
  /** How far the timeline scrolled, in physical px (signed for right-to-left). */
  shift: number;
  rtl: boolean;
  contentW: number;
  stretch: SVGSVGElement | null;
  overlay: SVGSVGElement | null;
  fade: SVGGElement | null;
};

/**
 * The animations of a zoom: the bars and grid (already drawn at the new zoom) stretch from where they
 * were, diamonds slide, labels fade back in. Returns the running animations (the first is the lead).
 * @internal
 */
export function startGanttGlide(o: GanttGlideInput): Animation[] {
  const { fromPx, px, shift, rtl, contentW, stretch, overlay, fade } = o;
  const k = fromPx / px;
  const origin = rtl ? contentW : 0;
  const timing: KeyframeAnimationOptions = { duration: duration.slower * 1000, easing: cssEase(ease.inOut) };
  const list: Animation[] = [];
  if (stretch && typeof stretch.animate === "function") {
    list.push(stretch.animate([{ transform: `translateX(${shift}px) scaleX(${k})` }, { transform: "none" }], timing));
    for (const node of overlay?.querySelectorAll<SVGElement>("[data-fx]") ?? []) {
      const x = Number(node.dataset.fx);
      list.push(
        node.animate([{ transform: `translateX(${(k - 1) * (x - origin) + shift}px)` }, { transform: "none" }], timing),
      );
    }
    if (fade) list.push(fade.animate([{ opacity: 0 }, { opacity: 0, offset: 0.55 }, { opacity: 1 }], timing));
  }
  return list;
}

"use client";

import { memo, useSyncExternalStore, type ReactNode } from "react";
import { motion } from "motion/react";
import { cn } from "../../lib/cn";
import { duration, spring } from "../../motion/tokens";
import { ChartAnnouncer } from "../chart-parts";
import { type GanttScale } from "./types";
import { HEADER_TOP, HEADER } from "./layout";
import { useActiveKey, type ActiveStore } from "./store";

/** Where the highlight behind the row being read goes (it glides between rows). */
export function useHighlight(store: ActiveStore, rowIndex: ReadonlyMap<string, number>, rowY: number[]) {
  const key = useActiveKey(store);
  const i = key === null ? -1 : (rowIndex.get(key) ?? -1);
  return { y: i >= 0 ? (rowY[i] ?? 0) : (rowY[0] ?? 0), opacity: i >= 0 ? 1 : 0 };
}
/** The transition of the row highlight as it glides between rows (instant under reduced motion). */
export const highlightGlide = (reduced: boolean) =>
  reduced ? { duration: 0 } : { y: spring.snappy, opacity: { duration: duration.fast } };

/** The sliding highlight behind the active row, in the task-name column. */
export const LabelHighlight = memo(function LabelHighlight({
  store,
  rowIndex,
  rowY,
  rowH,
  reduced,
}: {
  store: ActiveStore;
  rowIndex: ReadonlyMap<string, number>;
  rowY: number[];
  rowH: number;
  reduced: boolean;
}) {
  return (
    <motion.div
      aria-hidden
      className="pointer-events-none absolute inset-x-1 top-0 rounded-sheen-sm bg-sheen-hover"
      initial={false}
      animate={useHighlight(store, rowIndex, rowY)}
      transition={highlightGlide(reduced)}
      style={{ height: rowH }}
    />
  );
});

/** The same highlight across the timeline. */
export const TimelineHighlight = memo(function TimelineHighlight({
  store,
  rowIndex,
  rowY,
  rowH,
  width,
  reduced,
}: {
  store: ActiveStore;
  rowIndex: ReadonlyMap<string, number>;
  rowY: number[];
  rowH: number;
  width: number;
  reduced: boolean;
}) {
  return (
    <motion.rect
      x={0}
      width={width}
      height={rowH}
      rx={6}
      className="fill-sheen-hover"
      initial={false}
      animate={useHighlight(store, rowIndex, rowY)}
      transition={highlightGlide(reduced)}
    />
  );
});

/** The tooltip (or the docked readout) of the task being read; `fallback` while none is. */
export function GanttReadout({
  store,
  read,
  fallback,
}: {
  store: ActiveStore;
  read: (key: string, scroll: number) => ReactNode;
  fallback: ReactNode;
}) {
  const key = useActiveKey(store);
  const scroll = useSyncExternalStore(
    store.subscribe,
    () => store.get().scroll,
    () => 0,
  );
  return (key === null ? null : read(key, scroll)) ?? fallback;
}

/** Announces the task being read (keyboard moves only: `text` returns "" for pointer reads). */
export function GanttAnnouncer({ store, text }: { store: ActiveStore; text: (key: string) => string }) {
  const key = useActiveKey(store);
  return <ChartAnnouncer text={key === null ? "" : text(key)} />;
}

/** The ticks of the timeline: the top header (months) and bottom header (days or weeks) with their day ranges and labels. */
export type Ticks = {
  top: { a: number; b: number; label: string; short: string }[];
  bottom: { a: number; b: number; label: string; weekend?: boolean }[];
};

/**
 * Weekend bands (day zoom) and the grid: a hairline per bottom tick, a firmer one per top tick.
 * Each kind is ONE path, so a zoom to days adds three nodes, not hundreds.
 */
export const GridLayer = memo(function GridLayer({
  ticks,
  weekends,
  rangeStart,
  px,
  contentW,
  height,
  rtl,
}: {
  ticks: Ticks;
  weekends: boolean;
  rangeStart: number;
  px: number;
  contentW: number;
  height: number;
  rtl: boolean;
}) {
  const at = (day: number) => {
    const o = (day - rangeStart) * px;
    return rtl ? contentW - o : o;
  };
  const r = (n: number) => Math.round(n * 10) / 10;
  let bands = "";
  if (weekends)
    for (const t of ticks.bottom)
      if (t.weekend)
        bands += `M${r(Math.min(at(t.a), at(t.b)))},${HEADER}h${r(px * (t.b - t.a))}V${height}h${-r(px * (t.b - t.a))}Z`;
  let minor = "";
  for (const t of ticks.bottom) minor += `M${r(at(t.a))},${HEADER_TOP}V${height}`;
  let major = "";
  for (const t of ticks.top) major += `M${r(at(t.a))},0V${height}`;
  return (
    <g className="pointer-events-none">
      {bands && <path d={bands} fill="var(--sheen-chart-grid)" opacity={0.6} />}
      {minor && <path d={minor} fill="none" stroke="var(--sheen-chart-grid)" />}
      {major && <path d={major} fill="none" className="stroke-sheen-border" />}
      <line x1={0} x2={contentW} y1={HEADER - 0.5} y2={HEADER - 0.5} className="stroke-sheen-border" />
    </g>
  );
});

/**
 * Header labels. The top tier (months, or years) is sticky: syncTimeline slides each label to stay
 * in view while its segment is; labels thin out when they would collide.
 */
export const HeaderLabels = memo(function HeaderLabels({
  ticks,
  scale,
  rangeStart,
  px,
  contentW,
  rtl,
  todayDay,
}: {
  ticks: Ticks;
  scale: GanttScale;
  rangeStart: number;
  px: number;
  contentW: number;
  rtl: boolean;
  todayDay: number | null;
}) {
  const offset = (day: number) => (day - rangeStart) * px;
  return (
    <g>
      {ticks.top.map((t) => {
        const w = (t.b - t.a) * px;
        const text = t.label.length * 6.6 + 12 <= w ? t.label : t.short.length * 6.6 + 12 <= w ? t.short : "";
        return text ? (
          <text
            key={`tl${t.a}:${text}`}
            data-sticky=""
            data-a={offset(t.a)}
            data-b={offset(t.b)}
            data-w={text.length * 6.6}
            visibility="hidden"
            y={HEADER_TOP - 8}
            className="fill-sheen-fg text-xs font-medium"
          >
            {text}
          </text>
        ) : null;
      })}
      {ticks.bottom.map((t) => {
        const w = (t.b - t.a) * px;
        if (t.label.length * 6.2 + 8 > w) return null;
        // Months (month zoom) are sticky too: a month cut by the edge of the view keeps its name.
        if (scale === "month")
          return (
            <text
              key={`bl${t.a}:${t.label}`}
              data-sticky=""
              data-a={offset(t.a)}
              data-b={offset(t.b)}
              data-w={t.label.length * 6.2}
              visibility="hidden"
              y={HEADER - 9}
              className="fill-sheen-fg-muted text-2xs tabular-nums"
            >
              {t.label}
            </text>
          );
        const s = offset(t.a);
        const x = rtl ? contentW - s - w : s;
        const isToday = scale === "day" && t.a === todayDay;
        return (
          <text
            key={`bl${t.a}`}
            x={scale === "day" ? x + w / 2 : x + (rtl ? w - 6 : 6)}
            y={HEADER - 9}
            textAnchor={scale === "day" ? "middle" : rtl ? "end" : "start"}
            className={cn(
              "text-2xs tabular-nums",
              isToday ? "fill-sheen-accent font-semibold" : t.weekend ? "fill-sheen-fg-subtle" : "fill-sheen-fg-muted",
            )}
          >
            {t.label}
          </text>
        );
      })}
    </g>
  );
});

/* ======================================================================
 * GanttChart
 * ====================================================================== */

"use client";

import { memo, useEffectEvent, useRef, type RefObject, useLayoutEffect } from "react";
import { usePresence } from "motion/react";
import { duration, ease } from "../../motion/tokens";
import { LegendKey } from "../chart-parts";
import { clamp, slotColor, TOOLTIP_DOCK_SPACE, type ChartColor } from "../chart-utils";
import { ChartTip } from "../heatmap";

/* ======================================================================
 * Small pieces
 * ====================================================================== */

/** Height of the band a narrow touch chart reserves above the timeline for the docked readout (two lines). */
export const DOCK_BAND = TOOLTIP_DOCK_SPACE + 18;

/** Height of the top header band of the timeline (the months), in px. */
export const HEADER_TOP = 24;
/** Height of the bottom header band of the timeline (the days or weeks), in px. */
export const HEADER_BOTTOM = 26;
/** Total height of the timeline header, in px. */
export const HEADER = HEADER_TOP + HEADER_BOTTOM;
/** Height of a task bar, in px. */
export const BAR_H = 20;
/** Size of a milestone diamond, in px. */
export const DIAMOND = 13;
/** Width of the fade at an edge of the timeline that has more plan beyond it. */
export const FADE = 28;
/** SVG labels keep their contrast where a line crosses them: a halo in the surface colour, under the glyphs. */
export const HALO =
  "[paint-order:stroke] [stroke-linejoin:round] [stroke-width:3px] [stroke:var(--sheen-chart-surface)] forced-colors:[stroke:Canvas]";

/** Wraps text in a first-strong isolate, so dates and numbers never reorder inside right-to-left text. */
export const isolate = (text: string) => (text ? `⁨${text}⁩` : text);
/** Formats an easing curve (four numbers) as a CSS `cubic-bezier()`. */
export const cssEase = (e: readonly number[]) => `cubic-bezier(${e.join(",")})`;
/** A drop-shadow filter that makes a bar glow in the colour of its slot in dark mode. */
export const glow = (slot: ChartColor | 0) =>
  `drop-shadow(0 0 6px light-dark(transparent, color-mix(in oklab, ${slotColor(slot)} 65%, transparent)))`;
/** The entrance cascade: row `order` starts `base` seconds in, a little after the row above. */
export const cascadeDelay = (order: number, base: number) => base + Math.min(0.7, order * 0.045);

/*
 * Rows are plain elements moved by Web Animations, not Motion components: a zoom or a collapse
 * re-renders every row of a long plan, and plain elements keep that cheap (no per-row animation
 * engine, no per-frame JavaScript).
 */

/**
 * A row's motion. Its place is baked into its geometry (no transform at rest: hundreds of rows
 * must not each become a transform node that every repaint has to layerize). When `y` changes (a
 * phase above collapsed or expanded) the row glides there: one Web Animation from its old place
 * (a FLIP offset) to none. A row added after the first view fades in when `appear` says so; a row
 * being removed fades out first (AnimatePresence). Long plans (`glide` false) just jump.
 */
export function useRow(
  ref: RefObject<HTMLElement | SVGElement | null>,
  y: number,
  reduced: boolean,
  firstView: RefObject<boolean>,
  { appear = false, glide = true }: { appear?: boolean; glide?: boolean } = {},
) {
  const [isPresent, safeToRemove] = usePresence();
  const lastY = useRef<number | null>(null);
  useLayoutEffect(() => {
    const el = ref.current;
    const prev = lastY.current;
    lastY.current = y;
    if (!el || reduced || typeof el.animate !== "function") return;
    if (prev === null) {
      if (appear && !firstView.current)
        el.animate([{ opacity: 0 }, { opacity: 1 }], { duration: duration.base * 1000, easing: cssEase(ease.out) });
      return;
    }
    if (prev === y) return;
    // Where the row shows now: its old place, plus what is left of a glide still running.
    let offset = prev - y;
    const running = el.getAnimations().filter((a) => a.id === "glide");
    if (running.length) {
      offset += new DOMMatrix(getComputedStyle(el).transform).f;
      running.forEach((a) => a.cancel());
    }
    if (!glide) return;
    const anim = el.animate([{ transform: `translateY(${offset}px)` }, { transform: "none" }], {
      duration: duration.slower * 1000,
      easing: cssEase(ease.out),
    });
    anim.id = "glide";
  }, [y, reduced, appear, glide, ref, firstView]);
  useLayoutEffect(() => {
    if (isPresent) return;
    const el = ref.current;
    if (!el || reduced || typeof el.animate !== "function") {
      safeToRemove();
      return;
    }
    const out = el.animate([{ opacity: 1 }, { opacity: 0 }], {
      duration: duration.exit * 1000,
      easing: cssEase(ease.exit),
      fill: "forwards",
    });
    out.finished.then(
      () => safeToRemove(),
      () => undefined,
    );
    return () => out.cancel();
  }, [isPresent, reduced, ref, safeToRemove]);
}

/**
 * A mark's first-view entrance: `keyframes` (one Web Animation, held at its first frame until its
 * delay is up), started when `play` turns on, or on mount after that. Returns true while the mark
 * waits for its entrance (style it invisible then).
 */
export function useEntranceAnimation(
  ref: RefObject<Element | null>,
  play: boolean,
  reduced: boolean,
  keyframes: () => Keyframe[],
  options: () => KeyframeAnimationOptions,
) {
  const done = useRef(false);
  const start = useEffectEvent(() => {
    const el = ref.current;
    if (!el || typeof el.animate !== "function") return;
    el.animate(keyframes(), { fill: "backwards", ...options() });
  });
  useLayoutEffect(() => {
    if (!play || done.current) return;
    done.current = true;
    if (!reduced) start();
  }, [play, reduced]);
  return !play && !reduced;
}

/**
 * The reading on a narrow touch chart, pinned in the band above the timeline: two fixed lines (the
 * task and its dates, then duration, progress, dependencies and owner), each truncated, so it never
 * spills over the header. Every part is bidi-isolated, so dates keep their order on right-to-left
 * pages. Visual only: the chart announces the same through ChartAnnouncer.
 */
export function DockedReadout({
  title,
  value,
  color,
  details,
}: {
  title: string;
  value: string;
  color: string;
  details: string[];
}) {
  return (
    <div
      aria-hidden
      data-slot="chart-readout"
      className="glass-3 pointer-events-none absolute inset-x-0 top-0 z-10 flex h-12 flex-col justify-center gap-0.5 rounded-sheen-md px-3 text-xs"
    >
      <p className="flex min-w-0 items-center gap-2">
        <LegendKey color={color} />
        <span dir="auto" className="min-w-0 truncate font-medium text-sheen-fg">
          {title}
        </span>
        <bdi className="ms-auto shrink-0 font-semibold text-sheen-fg tabular-nums">{value}</bdi>
      </p>
      <p dir="auto" className="truncate text-sheen-fg-muted">
        {details.map((part, i) => (
          <span key={i}>
            {i > 0 && " · "}
            <bdi>{part}</bdi>
          </span>
        ))}
      </p>
    </div>
  );
}

/** ChartTip measures itself on every render: render it only when what it shows (or where) changes. */
export const StableTip = memo(ChartTip, (a, b) => JSON.stringify(a) === JSON.stringify(b));

/**
 * Everything that follows the horizontal scroll, written straight to the DOM (no React render per
 * scroll frame): the sticky month / year labels, labels cut by the edge of the view, and the edge
 * fades. Geometry is read from the overlay's data attributes, so this needs no closure.
 */
export function syncTimeline(scroller: HTMLElement, overlay: SVGSVGElement, pos: number) {
  const contentW = Number(overlay.dataset.cw);
  const viewW = Number(overlay.dataset.vw);
  const rtl = overlay.dataset.rtl === "true";
  for (const label of overlay.querySelectorAll<SVGTextElement>("[data-sticky]")) {
    const a = Number(label.dataset.a);
    const b = Number(label.dataset.b);
    const w = Number(label.dataset.w);
    // The label stays in view while any of its segment is; it hides once it's being pushed out.
    const at = clamp(pos + 8, a + 6, Math.max(a + 6, b - w - 6));
    if (at < pos + 2) {
      if (label.getAttribute("visibility") !== "hidden") label.setAttribute("visibility", "hidden");
      continue;
    }
    const x = String(Math.round((rtl ? contentW - at - w : at) * 10) / 10);
    if (label.getAttribute("x") !== x) label.setAttribute("x", x);
    if (label.hasAttribute("visibility")) label.removeAttribute("visibility");
  }
  // A label the edge of the view would cut fades out rather than show a stray "%".
  for (const label of overlay.querySelectorAll<SVGElement>("[data-fit]")) {
    const o = Number(label.dataset.o);
    const w = Number(label.dataset.w);
    label.toggleAttribute("data-out", !(o >= pos - 0.5 && o + w <= pos + viewW - 0.5));
  }
  // Fade an edge only while there is more plan beyond it. (The widths come from the geometry, so
  // this never forces a layout.)
  const max = Math.max(0, contentW - viewW);
  const more = { start: pos > 1, end: pos < max - 1 };
  const left = rtl ? more.end : more.start;
  const right = rtl ? more.start : more.end;
  const key = `${+left}${+right}`;
  if (scroller.dataset.edges !== key) {
    scroller.dataset.edges = key;
    scroller.toggleAttribute("data-fade", left || right);
    scroller.style.setProperty("--gantt-fade-l", `${left ? FADE : 0}px`);
    scroller.style.setProperty("--gantt-fade-r", `${right ? FADE : 0}px`);
  }
}

/** The small round marker, in the group's colour, before a group's name. */
export function GroupDot({ color }: { color: ChartColor | 0 }) {
  return (
    <span
      aria-hidden
      className="size-2 shrink-0 rounded-full forced-colors:border forced-colors:border-[CanvasText]"
      style={{ backgroundColor: slotColor(color) }}
    />
  );
}

/* ---------- Scrolling in either direction ---------- */

/** Distance scrolled from the inline start (positive in LTR and RTL alike). */
export function scrollStart(el: HTMLElement, rtl: boolean) {
  return rtl ? -el.scrollLeft : el.scrollLeft;
}

/** Scrolls to an offset from the inline start (works in LTR and RTL), optionally smoothly. */
export function setScrollStart(el: HTMLElement, rtl: boolean, offset: number, smooth = false) {
  const max = Math.max(0, el.scrollWidth - el.clientWidth);
  const v = clamp(offset, 0, max);
  el.scrollTo({ left: rtl ? -v : v, behavior: smooth ? "smooth" : "auto" });
}

import { type LegendItem } from "../chart-parts";
import { clamp, slotColor, type ChartColor, itemAt } from "../chart-utils";
import { type GanttTask, type GanttScale } from "./types";

/* ======================================================================
 * Dates as day numbers (UTC days since 1970), so time zones never shift a task.
 * ====================================================================== */

/** Milliseconds in one day. */
export const DAY_MS = 86_400_000;

/** A date (Date or "YYYY-MM-DD" string, read as a local date) as a day number; null if invalid. */
export function ganttDay(d: Date | string | undefined | null): number | null {
  if (d === undefined || d === null) return null;
  if (d instanceof Date)
    return Number.isNaN(d.getTime()) ? null : Math.round(Date.UTC(d.getFullYear(), d.getMonth(), d.getDate()) / DAY_MS);
  const m = /^(\d{4})-(\d{2})-(\d{2})$/.exec(d.trim());
  if (m) return Math.round(Date.UTC(Number(m[1]), Number(m[2]) - 1, Number(m[3])) / DAY_MS);
  const t = new Date(d);
  return Number.isNaN(t.getTime()) ? null : ganttDay(t);
}

/** The local Date (midnight) of a day number, for Intl formatting. */
export function dateOf(day: number) {
  const u = new Date(day * DAY_MS);
  return new Date(u.getUTCFullYear(), u.getUTCMonth(), u.getUTCDate());
}

/** The day of the week of a day number (0 is Sunday); 1970-01-01 was a Thursday. */
export const weekday = (day: number) => ((day % 7) + 7 + 4) % 7; // 1970-01-01 was a Thursday
/** The UTC year, month (0-11) and day of the month of a day number. */
export const ymd = (day: number) => {
  const u = new Date(day * DAY_MS);
  return { y: u.getUTCFullYear(), m: u.getUTCMonth(), d: u.getUTCDate() };
};
/** The day number of the first day of month `m` (0-11) of year `y`. */
export const monthStart = (y: number, m: number) => Math.round(Date.UTC(y, m, 1) / DAY_MS);

/** Pixels per day at each zoom (before stretching to fill the width). */
export const PX_PER_DAY: Record<GanttScale, number> = { day: 34, week: 14, month: 4.5 };
/** The zoom levels from the coarsest to the finest. */
export const ORDER: GanttScale[] = ["month", "week", "day"];

/* ======================================================================
 * Model
 * ====================================================================== */

/** A task as a row of the timeline: its dates (day numbers, end exclusive), milestone flag, progress, colour slot and group. */
export type TaskRow = {
  kind: "task";
  key: string;
  index: number;
  task: GanttTask;
  start: number;
  /** Exclusive end day. */
  end: number;
  milestone: boolean;
  progress: number | null;
  color: ChartColor | 0;
  group: string | null;
};
/** A group heading row: the span of its tasks, how many there are and its colour slot. */
export type GroupRow = {
  kind: "group";
  key: string;
  name: string;
  start: number;
  end: number;
  count: number;
  color: ChartColor | 0;
};
/** One row of the timeline: a task or a group. */
export type Row = TaskRow | GroupRow;

/** The colour slot (1-8) of the group at position `i`; 0 (neutral) past the eighth. */
export function slotOf(i: number): ChartColor | 0 {
  return i >= 0 && i < 8 ? ((i + 1) as ChartColor) : 0;
}

/** Turns the tasks of the props into the rows and the dates of the timeline (pure, safe to call on the server). */
export function buildModel(tasks: readonly GanttTask[]) {
  const groups: string[] = [];
  for (const t of tasks) if (t.group && !groups.includes(t.group)) groups.push(t.group);
  const taskRows: TaskRow[] = [];
  tasks.forEach((task, index) => {
    const s = ganttDay(task.start);
    if (s === null) return;
    const milestone = !!task.milestone;
    let e = milestone ? s : (ganttDay(task.end) ?? s);
    let start = s;
    if (e < start) [start, e] = [e, start];
    const groupIndex = task.group ? groups.indexOf(task.group) : -1;
    taskRows.push({
      kind: "task",
      key: task.id,
      index,
      task,
      start,
      end: e + 1,
      milestone,
      progress: typeof task.progress === "number" && Number.isFinite(task.progress) ? clamp(task.progress, 0, 1) : null,
      color: task.color ?? (groupIndex >= 0 ? slotOf(groupIndex) : 1),
      group: task.group ?? null,
    });
  });
  return { taskRows, groups };
}

/** Rounded orthogonal path through `pts` (corner radius r). */
export function roundedPath(pts: [number, number][], r = 5) {
  if (pts.length < 2) return "";
  let d = `M${itemAt(pts, 0)[0]},${itemAt(pts, 0)[1]}`;
  for (let i = 1; i < pts.length - 1; i++) {
    const [px, py] = itemAt(pts, i - 1);
    const [x, y] = itemAt(pts, i);
    const [nx, ny] = itemAt(pts, i + 1);
    const l1 = Math.hypot(x - px, y - py);
    const l2 = Math.hypot(nx - x, ny - y);
    const rr = Math.min(r, l1 / 2, l2 / 2);
    if (rr < 0.5) {
      d += `L${x},${y}`;
      continue;
    }
    const ax = x - ((x - px) / l1) * rr;
    const ay = y - ((y - py) / l1) * rr;
    const bx = x + ((nx - x) / l2) * rr;
    const by = y + ((ny - y) / l2) * rr;
    d += `L${ax.toFixed(1)},${ay.toFixed(1)}Q${x},${y} ${bx.toFixed(1)},${by.toFixed(1)}`;
  }
  const last = itemAt(pts, pts.length - 1);
  return `${d}L${last[0]},${last[1]}`;
}

/** Legend items for a ChartCard: one per group (phase), in its fixed colour slot. */
export function ganttLegend(tasks: readonly GanttTask[]): LegendItem[] {
  const { groups } = buildModel(tasks);
  return groups.map((g, i) => ({ label: g, color: slotColor(slotOf(i)), kind: "rect" as const }));
}

"use client";

import type { RefObject } from "react";
import { AnimatePresence } from "motion/react";
import { DIAMOND, HEADER } from "./layout";
import { dateOf, type Row } from "./model";
import { MilestoneMark, RowLabel } from "./rows";
import type { ActiveStore } from "./store";
import type { ganttFormats } from "./ticks";
import { HeaderLabels, type Ticks } from "./layers";
import type { GanttScale } from "./types";

/** The text layer over the timeline: never stretched by a zoom glide; labels fade back in after it. */
export function GanttOverlay({
  svgRef,
  fadeRef,
  store,
  rows,
  rowY,
  rowH,
  ticks,
  scale,
  rangeStart,
  px,
  contentW,
  viewW,
  height,
  rtl,
  todayDay,
  todayIn,
  todayX,
  X,
  xOf,
  fmt,
  pct,
  play,
  reduced,
  glide,
  firstView,
}: {
  svgRef: RefObject<SVGSVGElement | null>;
  fadeRef: RefObject<SVGGElement | null>;
  store: ActiveStore;
  rows: Row[];
  rowY: number[];
  rowH: number;
  ticks: Ticks;
  scale: GanttScale;
  rangeStart: number;
  px: number;
  contentW: number;
  viewW: number;
  height: number;
  rtl: boolean;
  todayDay: number | null;
  todayIn: boolean;
  todayX: number;
  /** Offset along the timeline → x on screen (mirrored for right-to-left). */
  X: (offset: number) => number;
  /** Day → offset along the timeline. */
  xOf: (day: number) => number;
  fmt: ReturnType<typeof ganttFormats>;
  pct: Intl.NumberFormat;
  play: boolean;
  reduced: boolean;
  glide: boolean;
  firstView: { current: boolean };
}) {
  return (
    <svg
      ref={svgRef}
      aria-hidden
      width={contentW}
      height={height}
      data-cw={contentW}
      data-vw={viewW}
      data-rtl={rtl}
      className="pointer-events-none absolute inset-0 block"
      style={{ direction: "ltr" }}
    >
      <g ref={fadeRef}>
        <HeaderLabels
          ticks={ticks}
          scale={scale}
          rangeStart={rangeStart}
          px={px}
          contentW={contentW}
          rtl={rtl}
          todayDay={todayIn ? todayDay : null}
        />
        <AnimatePresence initial={false}>
          {rows.map((row, i) => {
            if (row.kind !== "task") return null;
            const y = rowY[i] ?? 0;
            if (row.milestone) {
              if (DIAMOND + 60 >= contentW) return null;
              const offset = xOf(row.start) + px / 2 + DIAMOND / 2 + 6;
              return (
                <RowLabel
                  key={row.key}
                  y={y}
                  x={X(offset)}
                  text={fmt.dayMonth.format(dateOf(row.start))}
                  rowH={rowH}
                  rowKey={row.key}
                  store={store}
                  rtl={rtl}
                  fitStart={offset}
                  order={i}
                  play={play}
                  reduced={reduced}
                  glide={glide}
                  firstView={firstView}
                />
              );
            }
            if (row.progress === null) return null;
            const barW = Math.max(2, xOf(row.end) - xOf(row.start) - 2);
            const offset = xOf(row.start) + barW + 6;
            return (
              <RowLabel
                key={row.key}
                y={y}
                x={X(offset)}
                text={pct.format(row.progress)}
                rowH={rowH}
                rowKey={row.key}
                store={store}
                rtl={rtl}
                fitStart={offset}
                order={i}
                play={play}
                reduced={reduced}
                glide={glide}
                firstView={firstView}
              />
            );
          })}
        </AnimatePresence>
      </g>
      <AnimatePresence initial={false}>
        {rows.map((row, i) =>
          row.kind === "task" && row.milestone ? (
            <MilestoneMark
              key={row.key}
              index={row.index}
              y={rowY[i] ?? 0}
              cx={X(xOf(row.start) + px / 2)}
              rowH={rowH}
              color={row.color}
              rowKey={row.key}
              store={store}
              order={i}
              play={play}
              reduced={reduced}
              glide={glide}
              firstView={firstView}
            />
          ) : null,
        )}
      </AnimatePresence>
      {/* Today's marker on the header rule (its line runs under the bars). */}
      {todayIn && (
        <circle
          data-fx={todayX}
          cx={todayX}
          cy={HEADER}
          r={3.5}
          className="fill-sheen-accent forced-colors:fill-[Highlight]"
        />
      )}
    </svg>
  );
}

"use client";

import { memo, useRef, useSyncExternalStore, type RefObject, useLayoutEffect } from "react";
import { motion } from "motion/react";
import { cn } from "../../lib/cn";
import { duration, ease } from "../../motion/tokens";
import { slotColor, type ChartColor } from "../chart-utils";
import { hueMix } from "../heatmap";
import { type Row } from "./model";
import { BAR_H, DIAMOND, HALO, cssEase, glow, cascadeDelay, useRow, useEntranceAnimation, GroupDot } from "./layout";
import { useActiveKey, useIsActive, type ActiveStore, type Links } from "./store";

/* ---------- Memoised rows: a hover re-renders only the rows that change ---------- */

/** Props of a row of the label column: the row, its position and its state. */
export type LabelRowProps = {
  row: Row;
  y: number;
  height: number;
  store: ActiveStore;
  links: Links;
  collapsed: boolean;
  collapsible: boolean;
  countText: string | null;
  reduced: boolean;
  /** False on long plans: rows jump instead of gliding. */
  glide: boolean;
  /** True during the chart's first render: rows present then don't fade in. */
  firstView: RefObject<boolean>;
  onEnter: (key: string) => void;
  onLeave: () => void;
  onToggle: (group: string) => void;
};

/** A row of the task-name column: a phase (a disclosure button) or a task name. */
export const LabelRow = memo(function LabelRow({
  row,
  y,
  height,
  store,
  links,
  collapsed,
  collapsible,
  countText,
  reduced,
  glide,
  firstView,
  onEnter,
  onLeave,
  onToggle,
}: LabelRowProps) {
  const ref = useRef<HTMLDivElement>(null);
  useRow(ref, y, reduced, firstView, { appear: true, glide });
  // Lit while its task is being read, or one linked to it by an arrow.
  const hot = useSyncExternalStore(
    store.subscribe,
    () => {
      const key = store.get().key;
      return row.kind === "task" && key !== null && (key === row.key || (links.get(key)?.has(row.key) ?? false));
    },
    () => false,
  );
  const name =
    row.kind === "group" ? (
      <>
        <GroupDot color={row.color} />
        <span dir="auto" className="truncate">
          {row.name}
        </span>
        {countText && (
          <span className="shrink-0 font-normal text-sheen-fg-muted">
            <span aria-hidden>· </span>
            <bdi>{countText}</bdi>
          </span>
        )}
      </>
    ) : null;
  return (
    <div
      ref={ref}
      className="absolute inset-x-0 flex items-center"
      style={{ height, top: y }}
      onPointerEnter={(e) => {
        if (e.pointerType === "mouse" && row.kind === "task") onEnter(row.key);
      }}
      onPointerLeave={(e) => {
        if (e.pointerType === "mouse") onLeave();
      }}
    >
      {row.kind === "group" ? (
        collapsible ? (
          <button
            type="button"
            aria-expanded={!collapsed}
            onClick={() => onToggle(row.name)}
            className={cn(
              "mx-1 flex h-full min-w-0 flex-1 items-center gap-1.5 rounded-sheen-sm px-1 text-start text-xs font-semibold text-sheen-fg",
              "transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover",
              "focus-visible:outline-solid focus-visible:outline-2 focus-visible:-outline-offset-2 focus-visible:outline-sheen-focus",
            )}
          >
            <svg
              aria-hidden
              width={10}
              height={10}
              viewBox="0 0 10 10"
              className={cn(
                "shrink-0 text-sheen-fg-muted motion-ok:transition-transform motion-ok:duration-(--sheen-duration-base) motion-ok:ease-sheen-out",
                collapsed ? "rtl:rotate-180" : "rotate-90",
              )}
            >
              <path
                d="M3.5 2l3 3-3 3"
                fill="none"
                stroke="currentColor"
                strokeWidth={1.5}
                strokeLinecap="round"
                strokeLinejoin="round"
              />
            </svg>
            {name}
          </button>
        ) : (
          <span className="flex min-w-0 items-center gap-1.5 px-2 text-xs font-semibold text-sheen-fg">{name}</span>
        )
      ) : (
        <span
          dir="auto"
          className={cn(
            "truncate pe-2 text-xs transition-colors duration-(--sheen-duration-fast)",
            row.group ? "ps-6" : "ps-2",
            // Colour only: a weight change would re-lay out (and widen) the name on every hover.
            hot ? "text-sheen-fg" : "text-sheen-fg-muted",
          )}
          title={row.task.label}
        >
          {row.milestone && (
            <svg
              aria-hidden
              width={8}
              height={8}
              viewBox="0 0 8 8"
              className="me-1.5 inline-block align-[-0.5px] text-sheen-fg-subtle"
            >
              <rect x={1.2} y={1.2} width={5.6} height={5.6} rx={1} transform="rotate(45 4 4)" fill="currentColor" />
            </svg>
          )}
          {row.task.label}
        </span>
      )}
    </div>
  );
});

/** Props of a row of the bar area: the row, its position and its state. */
export type BarRowProps = {
  index: number;
  y: number;
  x: number;
  w: number;
  rowH: number;
  color: ChartColor | 0;
  progress: number | null;
  rowKey: string;
  store: ActiveStore;
  rtl: boolean;
  play: boolean;
  reduced: boolean;
  order: number;
  glide: boolean;
  firstView: RefObject<boolean>;
};

/** A task bar: tinted for the whole task, full colour for what's done; it grows from its start date. */
export const BarRow = memo(function BarRow({
  index,
  y,
  x,
  w,
  rowH,
  color,
  progress,
  rowKey,
  store,
  rtl,
  play,
  reduced,
  order,
  glide,
  firstView,
}: BarRowProps) {
  const hot = useIsActive(store, rowKey);
  const rowRef = useRef<SVGGElement>(null);
  const growRef = useRef<SVGGElement>(null);
  const doneRef = useRef<SVGPathElement>(null);
  useRow(rowRef, y, reduced, firstView, { glide });
  // A progress change glides: the done part is drawn at its new width, then scaled from the old one.
  const lastProgress = useRef(progress);
  useLayoutEffect(() => {
    const prev = lastProgress.current;
    lastProgress.current = progress;
    const el = doneRef.current;
    if (
      reduced ||
      !el ||
      typeof el.animate !== "function" ||
      prev === null ||
      progress === null ||
      prev === progress ||
      progress <= 0
    )
      return;
    el.animate([{ transform: `scaleX(${prev / progress})` }, { transform: "none" }], {
      duration: duration.slow * 1000,
      easing: cssEase(ease.inOut),
    });
  }, [progress, reduced]);
  const waiting = useEntranceAnimation(
    growRef,
    play,
    reduced,
    () => [{ transform: "scaleX(0)" }, { transform: "none" }],
    () => ({ duration: duration.slow * 1000, delay: cascadeDelay(order, 0.05) * 1000, easing: cssEase(ease.out) }),
  );
  const c = slotColor(color);
  const origin = rtl ? "right center" : "left center";
  const top = y + (rowH - BAR_H) / 2;
  const doneW = progress === null ? 0 : w * progress;
  return (
    <g ref={rowRef}>
      <g
        data-task={index}
        ref={growRef}
        style={{ transformBox: "fill-box", transformOrigin: origin, transform: waiting ? "scaleX(0)" : undefined }}
      >
        <g style={{ filter: hot ? glow(color) : undefined }}>
          <rect
            x={x}
            y={top}
            width={w}
            height={BAR_H}
            rx={4}
            style={{ fill: progress === null ? c : hueMix(color || 1, 0.3) }}
            className="forced-colors:stroke-[CanvasText]"
          />
          {/* What's done, from the task's start: rounded at the start (and at the end once complete).
              A shaped path rather than a clip: a clip per bar would cost a paint chunk per bar. */}
          {progress !== null && doneW > 0 && (
            <path
              ref={doneRef}
              d={donePath(x, top, w, doneW, rtl)}
              style={{ fill: c, transformBox: "fill-box", transformOrigin: origin }}
            />
          )}
          {/* Hairline top sheen: a touch of depth on every bar. */}
          <rect
            x={x + 3}
            y={top + 1}
            width={Math.max(0, w - 6)}
            height={1}
            className="pointer-events-none"
            fill="var(--sheen-chart-surface)"
            opacity={0.35}
          />
        </g>
      </g>
    </g>
  );
});

/**
 * The done part of a bar `w` wide at `x`: `doneW` from its start, with the bar's 4px corners at
 * the start, and at the end too once it reaches it.
 */
export function donePath(x: number, y: number, w: number, doneW: number, rtl: boolean) {
  const r = Math.min(4, doneW / 2, BAR_H / 2);
  const full = doneW >= w - 0.5;
  const re = full ? r : 0; // the end's corner radius
  const a = rtl ? x + w : x; // the start edge
  const b = rtl ? a - doneW : a + doneW; // the end edge
  const s = rtl ? -1 : 1; // inline direction
  const f = (n: number) => Math.round(n * 100) / 100;
  // Start top corner → end top → end bottom → start bottom, every corner an arc.
  return (
    `M${f(a + s * r)},${f(y)}H${f(b - s * re)}` +
    (re ? `A${f(re)},${f(re)} 0 0 ${rtl ? 0 : 1} ${f(b)},${f(y + re)}` : "") +
    `V${f(y + BAR_H - re)}` +
    (re ? `A${f(re)},${f(re)} 0 0 ${rtl ? 0 : 1} ${f(b - s * re)},${f(y + BAR_H)}` : "") +
    `H${f(a + s * r)}A${f(r)},${f(r)} 0 0 ${rtl ? 0 : 1} ${f(a)},${f(y + BAR_H - r)}V${f(y + r)}A${f(r)},${f(r)} 0 0 ${rtl ? 0 : 1} ${f(a + s * r)},${f(y)}Z`
  );
}

/** A phase summary: a bracket spanning the phase. */
export const GroupBracket = memo(function GroupBracket({
  y,
  x,
  w,
  groupH,
  color,
  order,
  play,
  reduced,
  glide,
  firstView,
}: {
  y: number;
  x: number;
  w: number;
  groupH: number;
  color: ChartColor | 0;
  order: number;
  play: boolean;
  reduced: boolean;
  glide: boolean;
  firstView: RefObject<boolean>;
}) {
  const ref = useRef<SVGGElement>(null);
  useRow(ref, y, reduced, firstView, { glide });
  const waiting = useEntranceAnimation(
    ref,
    play,
    reduced,
    () => [{ opacity: 0 }, { opacity: 1 }],
    () => ({ duration: duration.slow * 1000, delay: cascadeDelay(order, 0) * 1000, easing: cssEase(ease.out) }),
  );
  return (
    <g ref={ref} style={{ opacity: waiting ? 0 : undefined }}>
      <path
        d={`M${x},${y + groupH / 2 + 6}V${y + groupH / 2 - 1}H${x + w}V${y + groupH / 2 + 6}`}
        fill="none"
        strokeWidth={2}
        strokeLinejoin="round"
        style={{ stroke: `color-mix(in oklab, ${slotColor(color)} 70%, var(--sheen-fg-subtle))` }}
        className="forced-colors:stroke-[CanvasText]"
      />
    </g>
  );
});

/** A milestone diamond. `data-fx` lets a zoom glide slide it (it never stretches). */
export const MilestoneMark = memo(function MilestoneMark({
  index,
  y,
  cx,
  rowH,
  color,
  rowKey,
  store,
  order,
  play,
  reduced,
  glide,
  firstView,
}: {
  index: number;
  y: number;
  cx: number;
  rowH: number;
  color: ChartColor | 0;
  rowKey: string;
  store: ActiveStore;
  order: number;
  play: boolean;
  reduced: boolean;
  glide: boolean;
  firstView: RefObject<boolean>;
}) {
  const hot = useIsActive(store, rowKey);
  const rowRef = useRef<SVGGElement>(null);
  const popRef = useRef<SVGGElement>(null);
  useRow(rowRef, y, reduced, firstView, { glide });
  // It pops in with a little overshoot (a playful moment, like spring.bouncy), after the bars.
  const waiting = useEntranceAnimation(
    popRef,
    play,
    reduced,
    () => [
      { transform: "scale(0) rotate(-45deg)" },
      { transform: "scale(1.14) rotate(3deg)", offset: 0.62 },
      { transform: "none" },
    ],
    () => ({
      duration: duration.slower * 1000,
      delay: (0.25 + Math.min(0.8, order * 0.045)) * 1000,
      easing: cssEase(ease.out),
    }),
  );
  return (
    <g ref={rowRef}>
      <g data-fx={cx}>
        <g
          ref={popRef}
          data-task={index}
          style={{ transformBox: "fill-box", transformOrigin: "center", transform: waiting ? "scale(0)" : undefined }}
        >
          <rect
            x={cx - DIAMOND / 2}
            y={y + rowH / 2 - DIAMOND / 2}
            width={DIAMOND}
            height={DIAMOND}
            rx={2.5}
            transform={`rotate(45 ${cx} ${y + rowH / 2})`}
            strokeWidth={2}
            style={{
              fill: slotColor(color),
              stroke: "var(--sheen-chart-surface)",
              filter: hot ? glow(color) : undefined,
            }}
            className="forced-colors:stroke-[CanvasText]"
          />
        </g>
      </g>
    </g>
  );
});

/** A bar's progress or a milestone's date, beside it. Hidden (by syncTimeline) while the view's edge would cut it. */
export const RowLabel = memo(function RowLabel({
  y,
  x,
  text,
  rowH,
  rowKey,
  store,
  rtl,
  fitStart,
  order,
  play,
  reduced,
  glide,
  firstView,
}: {
  y: number;
  x: number;
  text: string;
  rowH: number;
  rowKey: string;
  store: ActiveStore;
  rtl: boolean;
  /** Offset of the label's start from the timeline's inline start (px). */
  fitStart: number;
  order: number;
  play: boolean;
  reduced: boolean;
  glide: boolean;
  firstView: RefObject<boolean>;
}) {
  const hot = useIsActive(store, rowKey);
  const rowRef = useRef<SVGGElement>(null);
  const textRef = useRef<SVGTextElement>(null);
  useRow(rowRef, y, reduced, firstView, { glide });
  const waiting = useEntranceAnimation(
    textRef,
    play,
    reduced,
    () => [{ opacity: 0 }, { opacity: 1 }],
    () => ({ duration: duration.slow * 1000, delay: cascadeDelay(order, 0.35) * 1000, easing: cssEase(ease.out) }),
