/** A dependency arrow. It draws in during the entrance; later (a hover lights it up) it just fades in. */
export const ArrowPath = memo(function ArrowPath({
  d,
  head,
  hot,
  order,
  play,
  reduced,
  settled,
}: {
  d: string;
  head: string;
  hot: boolean;
  order: number;
  play: boolean;
  reduced: boolean;
  settled: boolean;
}) {
  const draw = !reduced && !settled;
  const delay = 0.55 + Math.min(0.6, order * 0.05);
  const instant = reduced || !play;
  return (
    <g>
      <motion.path
        d={d}
        strokeWidth={hot ? 1.75 : 1.25}
        initial={reduced ? false : draw ? { pathLength: 0 } : { opacity: 0 }}
        animate={play ? (draw ? { pathLength: 1 } : { opacity: 1 }) : undefined}
        transition={
          instant
            ? { duration: 0 }
            : draw
              ? { duration: duration.slow, ease: ease.out, delay }
              : { duration: duration.fast }
        }
      />
      <motion.path
        d={head}
        strokeWidth={hot ? 1.75 : 1.25}
        initial={reduced ? false : { opacity: 0 }}
        animate={play ? { opacity: 1 } : undefined}
        transition={
          instant
            ? { duration: 0 }
            : draw
              ? { duration: duration.fast, delay: delay + duration.slow }
              : { duration: duration.fast }
        }
      />
    </g>
  );
});

/** A dependency arrow between two tasks: the keys of both, its path and its arrowhead. */
export type Arrow = { key: string; from: string; to: string; d: string; head: string };

/** Every arrow, under the bars; dimmed while a task is being read (re-renders only on that flip). */
export const IdleArrows = memo(function IdleArrows({
  store,
  arrows,
  play,
  reduced,
  settled,
}: {
  store: ActiveStore;
  arrows: Arrow[];
  play: boolean;
  reduced: boolean;
  settled: boolean;
}) {
  const reading = useSyncExternalStore(
    store.subscribe,
    () => store.get().key !== null,
    () => false,
  );
  return (
    <g
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      opacity={reading ? 0.4 : 0.75}
      className="pointer-events-none stroke-sheen-fg-subtle forced-colors:stroke-[CanvasText]"
    >
      {arrows.map((a, i) => (
        <ArrowPath
          key={a.key}
          d={a.d}
          head={a.head}
          hot={false}
          order={i}
          play={play}
          reduced={reduced}
          settled={settled}
        />
      ))}
    </g>
  );
});

/** The arrows of the task being read, lit up above the bars (plain paths that fade in: cheap to add on hover). */
export const HotArrows = memo(function HotArrows({
  store,
  arrows,
  fadeIn,
}: {
  store: ActiveStore;
  arrows: Arrow[];
  fadeIn: (el: SVGGElement | null) => void;
}) {
  const key = useActiveKey(store);
  return (
    <g
      fill="none"
      strokeLinecap="round"
      strokeLinejoin="round"
      strokeWidth={1.75}
      className="pointer-events-none stroke-sheen-fg forced-colors:stroke-[CanvasText]"
    >
      {key !== null &&
        arrows.map((a) =>
          a.from === key || a.to === key ? (
            <g key={a.key} ref={fadeIn}>
              <path d={a.d} />
              <path d={a.head} />
            </g>
          ) : null,
        )}
    </g>
  );
});

"use client";

import { useSyncExternalStore } from "react";

/* ---------- The task being read: a tiny store, so a hover never re-renders the chart ---------- */

/** The task being read (its key, or null) and the scroll position its tooltip was placed for. */
export type ActiveState = { key: string | null; scroll: number };

/**
 * Which task is being read, and the scroll position its tooltip was placed for. Outside React
 * state on purpose: a hover changes it on every row it crosses, and only the few pieces that show
 * it (the two rows that light up, the highlight, the arrows, the tooltip) subscribe and re-render;
 * the chart itself, with every bar and tick, never does. Long plans stay smooth.
 */
export function createActiveStore() {
  let state: ActiveState = { key: null, scroll: 0 };
  const listeners = new Set<() => void>();
  return {
    get: () => state,
    set: (next: ActiveState) => {
      if (next.key === state.key && next.scroll === state.scroll) return;
      state = next;
      for (const l of listeners) l();
    },
    subscribe: (listener: () => void) => {
      listeners.add(listener);
      return () => void listeners.delete(listener);
    },
  };
}
/** The store that holds the active task. */
export type ActiveStore = ReturnType<typeof createActiveStore>;
/** Each task's partners: the tasks one of its arrows connects it to (either way). */
export type Links = ReadonlyMap<string, ReadonlySet<string>>;

/** Subscribes to the key of the active task (null when none). */
export const useActiveKey = (store: ActiveStore) =>
  useSyncExternalStore(
    store.subscribe,
    () => store.get().key,
    () => null,
  );
/** Subscribes to whether the task with the given key is the active one. */
export const useIsActive = (store: ActiveStore, key: string) =>
  useSyncExternalStore(
    store.subscribe,
    () => store.get().key === key,
    () => false,
  );

import { type ReactNode } from "react";
import { ChartValueTable, MissingValue } from "../heatmap";
import { defaultGanttChartLabels, type GanttChartProps } from "./types";
import { dateOf, buildModel } from "./model";

/* ======================================================================
 * Table view
 * ====================================================================== */

/**
 * Props of GanttTable, the table view of the chart: the chart's data and formatting props plus a
 * hidden `caption` for screen readers.
 */
export type GanttTableProps = Pick<GanttChartProps, "tasks" | "locale" | "labels"> & {
  /** Sets a visually hidden caption that names the table. */
  caption?: string;
  /** Shown when there are no tasks. */
  emptyState?: ReactNode;
};

/**
 * Every task as a row: phase, start, end, duration, progress, owner and what it waits for.
 *
 * Props: the chart's `tasks`, `locale` and `labels`, plus `caption` (hidden, names the table) and `emptyState`. A real table: each task's phase, start, end, duration, progress, owner and what it waits for. Static (no motion). Pass it to `ChartCard table`.
 *
 * @example
 * ```tsx
 * import { GanttTable } from "@sheenui/theme";
 *
 * export function Example() {
 *   return (
 *     <GanttTable tasks={[{ id: "design", label: "Design", start: "2026-03-02", end: "2026-03-11", progress: 1 }]} caption="Project plan" />
 *   );
 * }
 * ```
 *
 * @see /charts/gantt
 */
export function GanttTable({ tasks, locale, labels: labelOverrides, caption, emptyState }: GanttTableProps) {
  const labels = { ...defaultGanttChartLabels, ...labelOverrides };
  const { taskRows, groups } = buildModel(tasks);
  const byId = new Map(taskRows.map((t) => [t.task.id, t.task.label]));
  let date: Intl.DateTimeFormat;
  let pct: Intl.NumberFormat;
  try {
    date = new Intl.DateTimeFormat(locale, { day: "numeric", month: "short", year: "numeric" });
    pct = new Intl.NumberFormat(locale, { style: "percent", maximumFractionDigits: 0 });
  } catch {
    date = new Intl.DateTimeFormat("en", { day: "numeric", month: "short", year: "numeric" });
    pct = new Intl.NumberFormat("en", { style: "percent", maximumFractionDigits: 0 });
  }
  return (
    <ChartValueTable
      caption={caption}
      emptyState={emptyState}
      columns={[
        { label: labels.task },
        ...(groups.length ? [{ label: labels.group, align: "start" as const }] : []),
        { label: labels.start, align: "start" },
        { label: labels.end, align: "start" },
        { label: labels.days },
        { label: labels.done },
        { label: labels.owner, align: "start" },
        { label: labels.dependsOn, align: "start" },
      ]}
      rows={taskRows.map((t) => [
        t.task.label,
        ...(groups.length ? [t.group ?? <MissingValue label={labels.none} />] : []),
        date.format(dateOf(t.start)),
        t.milestone ? labels.milestone : date.format(dateOf(t.end - 1)),
        t.milestone ? "0" : String(t.end - t.start),
        t.progress === null || t.milestone ? <MissingValue label={labels.none} /> : pct.format(t.progress),
        t.task.assignee ?? <MissingValue label={labels.none} />,
        (t.task.dependencies ?? [])
          .map((id) => byId.get(id))
          .filter(Boolean)
          .join(", ") || <MissingValue label={labels.none} />,
      ])}
    />
  );
}

import { DAY_MS, dateOf, monthStart, weekday, ymd } from "./model";
import type { Ticks } from "./layers";
import type { GanttScale } from "./types";

/** The `Intl.DateTimeFormat`s of the header tiers, in the chart's locale (English when it is unknown). @internal */
export function ganttFormats(locale: string | undefined) {
  const make = (o: Intl.DateTimeFormatOptions) => {
    try {
      return new Intl.DateTimeFormat(locale, o);
    } catch {
      return new Intl.DateTimeFormat("en", o);
    }
  };
  return {
    day: make({ day: "numeric" }),
    dayMonth: make({ day: "numeric", month: "short" }),
    monthShort: make({ month: "short" }),
    monthYear: make({ month: "long", year: "numeric" }),
    monthYearShort: make({ month: "short", year: "numeric" }),
    year: make({ year: "numeric" }),
    full: make({ day: "numeric", month: "short", year: "numeric" }),
  };
}

/**
 * The two header tiers of the timeline: months (or years at month zoom) on top, days, weeks or months
 * below, each as a `[a, b)` span of days with its label.
 * @internal
 */
export function buildTicks(
  rangeStart: number,
  rangeEnd: number,
  scale: GanttScale,
  fmt: ReturnType<typeof ganttFormats>,
  weekStart: number,
): Ticks {
  const top: Ticks["top"] = [];
  const bottom: Ticks["bottom"] = [];
  // Top tier: months (day / week zoom) or years (month zoom).
  let d = rangeStart;
  while (d < rangeEnd) {
    const { y, m } = ymd(d);
    if (scale === "month") {
      const next = Math.round(Date.UTC(y + 1, 0, 1) / DAY_MS);
      top.push({
        a: d,
        b: Math.min(next, rangeEnd),
        label: fmt.year.format(dateOf(d)),
        short: fmt.year.format(dateOf(d)),
      });
      d = next;
    } else {
      const next = monthStart(y, m + 1);
      top.push({
        a: d,
        b: Math.min(next, rangeEnd),
        label: fmt.monthYear.format(dateOf(d)),
        short: fmt.monthYearShort.format(dateOf(d)),
      });
      d = next;
    }
  }
  if (scale === "day") {
    for (let day = rangeStart; day < rangeEnd; day++) {
      const wd = weekday(day);
      bottom.push({ a: day, b: day + 1, label: fmt.day.format(dateOf(day)), weekend: wd === 0 || wd === 6 });
    }
  } else if (scale === "week") {
    let w = rangeStart - ((weekday(rangeStart) - weekStart + 7) % 7);
    while (w < rangeEnd) {
      bottom.push({
        a: Math.max(w, rangeStart),
        b: Math.min(w + 7, rangeEnd),
        label: fmt.dayMonth.format(dateOf(w)),
      });
      w += 7;
    }
  } else {
    let m = rangeStart;
    while (m < rangeEnd) {
      const { y, m: mo } = ymd(m);
      const next = monthStart(y, mo + 1);
      bottom.push({ a: m, b: Math.min(next, rangeEnd), label: fmt.monthShort.format(dateOf(m)) });
      m = next;
    }
  }
  return { top, bottom };
}

"use client";

import { cn } from "../../lib/cn";
import { SegmentedControl } from "../../segmented/segmented";
import type { GanttChartLabels, GanttScale } from "./types";

/** Narrows the switch's string value to a scale; anything else is ignored. */
function isGanttScale(v: unknown): v is GanttScale {
  return v === "day" || v === "week" || v === "month";
}

/** The Today button and the day / week / month switch above the timeline. */
export function GanttToolbar({
  labels,
  scale,
  onScale,
  showToday,
  todayEnabled,
  onToday,
}: {
  labels: GanttChartLabels;
  scale: GanttScale;
  onScale: (scale: GanttScale) => void;
  /** Whether the plan has a today date to jump to. */
  showToday: boolean;
  /** Whether that date falls inside the plan's range. */
  todayEnabled: boolean;
  onToday: () => void;
}) {
  return (
    <div className="flex flex-wrap items-center justify-end gap-2">
      {showToday && (
        <button
          type="button"
          disabled={!todayEnabled}
          onClick={onToday}
          className={cn(
            "glass-1 inline-flex h-7 items-center gap-1.5 rounded-sheen-full px-3 text-xs font-medium text-sheen-fg",
            "transition-colors duration-(--sheen-duration-fast) hover:bg-sheen-hover disabled:text-sheen-fg-subtle disabled:hover:bg-transparent",
            "any-pointer-coarse:h-11 motion-ok:active:scale-[0.97]",
            "focus-visible:outline-solid focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-sheen-focus",
          )}
        >
          <svg aria-hidden width={12} height={12} viewBox="0 0 12 12" className="shrink-0">
            <circle cx={6} cy={6} r={2.5} className="fill-sheen-accent" />
            <circle cx={6} cy={6} r={5} fill="none" className="stroke-sheen-accent" strokeWidth={1} opacity={0.5} />
          </svg>
          {labels.today}
        </button>
      )}
      <SegmentedControl
        size="sm"
        aria-label={labels.scaleLabel}
        value={scale}
        onValueChange={(v) => {
          if (isGanttScale(v)) onScale(v);
        }}
        items={[
          { value: "day", label: labels.day },
          { value: "week", label: labels.week },
          { value: "month", label: labels.month },
        ]}
      />
    </div>
  );
}

import { type ReactNode } from "react";
import { type ChartColor, type ChartInstructions } from "../chart-utils";

/* ======================================================================
 * Types
 * ====================================================================== */

/**
 * One task of a GanttChart: id, label, start and end, and optionally progress, dependencies,
 * milestone, group, colour and assignee.
 */
export type GanttTask = {
  /** Unique id, used by `dependencies`. */
  id: string;
  label: string;
  /** First day ("2026-03-02" is read as a local date, never shifted by time zones). */
  start: Date | string;
  /** Last day, inclusive (a task from the 2nd to the 6th covers 5 days). Ignored for milestones. */
  end?: Date | string;
  /** Share done, 0–1. */
  progress?: number;
  /** Ids of the tasks that must finish first (finish-to-start arrows). */
  dependencies?: readonly string[];
  /** A single-day marker (a diamond) instead of a bar. */
  milestone?: boolean;
  /** Phase or team: tasks are grouped under it (collapsible), and coloured by it. */
  group?: string;
  /** Colour slot 1–8. Default: the group's slot (in order of first appearance), else 1. */
  color?: ChartColor;
  /** Owner, shown in the tooltip and the table. */
  assignee?: string;
};

/** The time scale of a GanttChart: `day`, `week` or `month`. */
export type GanttScale = "day" | "week" | "month";

/**
 * Every string GanttChart speaks or shows, so it can be translated: pass a `Partial` as the `labels`
 * prop. Entries that need a value are functions.
 */
export type GanttChartLabels = {
  /** Appended to the timeline's accessible name. */
  instructions: ChartInstructions;
  roleDescription: string;
  /** The today line's label and the "jump to today" button. */
  today: string;
  /** Accessible name of the zoom switch, and its options. */
  scaleLabel: string;
  day: string;
  week: string;
  month: string;
  /** Header of the task-name column. */
  task: string;
  duration: (days: number) => string;
  /** Tooltip line for progress; `percent` is pre-formatted. */
  progress: (percent: string) => string;
  /** Tooltip line listing the tasks this one waits for. */
  after: (names: string) => string;
  milestone: string;
  /** Second part of a group row: how many tasks it holds. */
  tasks: (n: number) => string;
  /** Shown in the readout band of a narrow touch chart while nothing is being read. */
  hint: string;
  /** Table headers. */
  group: string;
  start: string;
  end: string;
  days: string;
  owner: string;
  dependsOn: string;
  done: string;
  /** Read for an empty table cell (no phase, owner, progress or dependency). */
  none: string;
};

/**
 * The built-in English strings of GanttChart; spread it into your own `labels` and change what you
 * need. This module is a client module, so use it from client code, not from a Server Component.
 */
export const defaultGanttChartLabels: GanttChartLabels = {
  instructions:
    "Use the up and down arrow keys to move between tasks, left and right to scroll the timeline, Home and End for the first and last task, T for today, plus and minus to zoom.",
  roleDescription: "Gantt chart",
  today: "Today",
  scaleLabel: "Timeline zoom",
  day: "Day",
  week: "Week",
  month: "Month",
  task: "Task",
  duration: (n) => (n === 1 ? "1 day" : `${n} days`),
  progress: (p) => `${p} done`,
  after: (names) => `After ${names}`,
  milestone: "Milestone",
  tasks: (n) => (n === 1 ? "1 task" : `${n} tasks`),
  hint: "Tap a bar for details",
  group: "Phase",
  start: "Start",
  end: "End",
  days: "Days",
  owner: "Owner",
  dependsOn: "Depends on",
  done: "Done",
  none: "None",
};

/**
 * Props of GanttChart. The component's own doc comment describes its behaviour, keyboard use and
 * accessibility.
 */
export type GanttChartProps = {
  /** The tasks: { id, label, start, end?, progress?, dependencies?, milestone?, group?, color?, assignee? }. `end` is the last day, inclusive; `milestone: true` marks a single day (and ignores `end`). */
  tasks: readonly GanttTask[];
  /** Current zoom level of the time axis; pass it with `onScaleChange` to control it. */
  scale?: GanttScale;
  /**
   * Sets the starting zoom when uncontrolled. Default "auto": the most detailed zoom at which the whole plan
   * fits the width (month when none does), so the first view never hides part of the plan.
   */
  defaultScale?: GanttScale | "auto";
  /** Called with "day", "week" or "month" when the zoom changes (controlled `scale`). */
  onScaleChange?: (scale: GanttScale) => void;
  /** Show the Day / Week / Month switch and the Today button. Default true. */
  toolbar?: boolean;
  /** Sets where the today line goes. Default: the current date; null hides it. */
  today?: Date | string | null;
  /** Locale of dates, numbers and the first day of the week. Default: the browser's. */
  locale?: string;
  /** Width of the task-name column in px. Default: fits the names, up to a third of the chart. */
  labelWidth?: number;
  /** Lets the person collapse and expand groups. Default true. */
  collapsible?: boolean;
  /** Groups that start collapsed. */
  defaultCollapsed?: readonly string[];
  /** Called with a task on click, Enter or Space. */
  onTaskClick?: (task: GanttTask) => void;
  /** Shown when there are no tasks. */
  emptyState?: ReactNode;
  /** Override the chart's strings (i18n). */
  labels?: Partial<GanttChartLabels>;
  /** Names the chart for assistive tech (required). */
  "aria-label": string;
  /** Adds extra classes to the outer element. */
  className?: string;
};

